<?php
require 'config.php'; require 'protecao.php';
if (!defined('TENANT_ID') || (function_exists('tem_acesso') && !tem_acesso('relatorios') && !tem_acesso('master'))) { http_response_code(403); exit('Acesso negado'); }
$tenant=(int)TENANT_ID;
$st=$pdo->prepare('SELECT COUNT(*) FROM eleitores WHERE tenant_id=?');$st->execute([$tenant]);$total=(int)$st->fetchColumn();
$st=$pdo->prepare('SELECT COUNT(*) FROM eleitor_tentativas_duplicadas WHERE tenant_id=?');$st->execute([$tenant]);$bloqueios=(int)$st->fetchColumn();
$st=$pdo->prepare('SELECT d.criado_em, e.nome AS eleitor, l.nome AS lideranca, d.origem FROM eleitor_tentativas_duplicadas d LEFT JOIN eleitores e ON e.id=d.eleitor_existente_id AND e.tenant_id=d.tenant_id LEFT JOIN eleitores l ON l.id=d.lideranca_solicitante_id AND l.tenant_id=d.tenant_id WHERE d.tenant_id=? ORDER BY d.id DESC LIMIT 200');$st->execute([$tenant]);$rows=$st->fetchAll(PDO::FETCH_ASSOC);
function eh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Indicações bloqueadas</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="admin_eleitores.php" class="btn btn-outline-secondary mb-3">Voltar à Base de Apoio</a><h2>Controle de indicações repetidas</h2><p class="text-muted">Bloqueios desde a instalação. Cadastros antigos não foram unificados; WhatsApp compartilhado pode gerar falso positivo e exige conferência administrativa.</p><div class="row g-3 mb-4"><div class="col-md-6"><div class="card p-3"><small>Registros atuais na base</small><h2><?= $total ?></h2></div></div><div class="col-md-6"><div class="card p-3"><small>Tentativas de duplicidade bloqueadas</small><h2><?= $bloqueios ?></h2></div></div></div><div class="table-responsive"><table class="table table-striped table-bordered bg-white"><thead><tr><th>Data</th><th>Eleitor existente</th><th>Liderança solicitante</th><th>Origem</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=eh($r['criado_em'])?></td><td><?=eh($r['eleitor']??'Cadastro removido')?></td><td><?=eh($r['lideranca']??'Sem liderança')?></td><td><?=eh($r['origem'])?></td></tr><?php endforeach; ?></tbody></table></div></main></body></html>